class Solution {
  public long maxSubarrays(int n, int[][] conflictingPairs) {
    int p = conflictingPairs.length;
    int[] head = new int[n + 1], next = new int[p];
    java.util.Arrays.fill(head, -1);
    for (int i = 0; i < p; i++) {
      int b = Math.max(conflictingPairs[i][0], conflictingPairs[i][1]);
      next[i] = head[b];
      head[b] = i;
    }
    long[] gain = new long[p];
    long base = 0;
    int max1 = 0, max2 = 0, id1 = -1;
    for (int r = 1; r <= n; r++) {
      for (int e = head[r]; e >= 0; e = next[e]) {
        int a = Math.min(conflictingPairs[e][0], conflictingPairs[e][1]);
        if (a > max1) {
          max2 = max1;
          max1 = a;
          id1 = e;
        } else if (a > max2) {
          max2 = a;
        }
      }
      base += r - max1;
      if (id1 >= 0) gain[id1] += max1 - max2;
    }
    long best = 0;
    for (long g : gain) best = Math.max(best, g);
    return base + best;
  }
}
